from qlib import Q
C='real-estate-math'
Q(C,'basic',"A rectangular lot is 150 feet by 290.4 feet. How many acres is it?","1 acre",[("2 acres","2 acres would be 87,120 square feet."),("0.5 acre","0.5 acre would be 21,780 square feet."),("4.4 acres","This divides by 10,000 instead of 43,560.")],"Acres = square feet ÷ 43,560","1. Area = 150 × 290.4 = 43,560 square feet.\n2. Acres = 43,560 ÷ 43,560 = **1 acre**.\n3. Remember: 1 acre = 43,560 square feet.",5,["area"])
Q(C,'basic',"A home sells for $300,000. The commission rate is 6%. What is the total commission?","$18,000",[("$1,800","This moves the decimal one place too far."),("$180,000","This uses 60% instead of 6%."),("$50,000","This divides the price by 6 instead of multiplying by 6%.")],"Commission = price × rate","1. Commission = Sale price × Rate.\n2. $300,000 × 0.06 = **$18,000**.\n3. Check: $18,000 ÷ $300,000 = 0.06.",5,["commission"])
Q(C,'intermediate',"A salesperson's broker receives a 6% commission on a $250,000 sale. The salesperson gets 60% of the broker's share. How much does the salesperson earn?","$9,000",[("$15,000","$15,000 is the whole commission before the split."),("$6,000","$6,000 is the broker's 40% share."),("$9,600","This uses the wrong split amount.")],"Total commission × agent's split","1. Total commission = $250,000 × 0.06 = $15,000.\n2. Salesperson's share = $15,000 × 0.60 = **$9,000**.\n3. Check: broker keeps $15,000 − $9,000 = $6,000 (40%).",5,["commission"])
Q(C,'intermediate',"A buyer is getting a loan with an 80% loan-to-value ratio on a $350,000 home. What is the loan amount?","$280,000",[("$70,000","$70,000 is the 20% down payment."),("$350,000","That is the full price, a 100% LTV."),("$300,000","This is not 80% of $350,000.")],"Loan = value × LTV","1. Loan = Price (or appraised value, if lower) × LTV.\n2. $350,000 × 0.80 = **$280,000**.\n3. Down payment = $350,000 − $280,000 = $70,000.",5,["LTV","financing"])
Q(C,'intermediate',"A lender charges 2 discount points on a $200,000 loan. How much do the points cost?","$4,000",[("$400","This uses 0.2% instead of 2%."),("$40,000","This uses 20% instead of 2%."),("$2,000","This treats 2 points as 1%.")],"1 point = 1% of the loan amount","1. One discount point = 1% of the **loan amount** (not the price).\n2. 2 points = 2% × $200,000 = **$4,000**.",5,["points","financing"])
Q(C,'advanced',"A home's assessed value is $180,000. The tax rate is 25 mills. What is the annual property tax?","$4,500",[("$450","This uses 2.5 mills by mistake."),("$45,000","This uses 25% instead of 25 mills."),("$7,200","This does not use the mill rate correctly.")],"1 mill = $1 per $1,000 = 0.001","1. 25 mills = 25 ÷ 1,000 = 0.025.\n2. Tax = $180,000 × 0.025 = **$4,500**.\n3. Check: $180,000 ÷ 1,000 × 25 = $4,500.",5,["property tax"])
Q(C,'advanced',"A seller wants to net $190,000 after paying a 5% commission. Ignoring other costs, what is the lowest sale price that will do this?","$200,000",[("$199,500","This adds 5% of $190,000 instead of dividing by 0.95."),("$180,500","This subtracts 5% instead of adding it back."),("$209,000","This adds 10% instead of 5%.")],"Price needed = desired net ÷ (1 − commission rate)","1. The seller keeps 100% − 5% = 95% of the price.\n2. Price = $190,000 ÷ 0.95 = **$200,000**.\n3. Check: $200,000 − 5% ($10,000) = $190,000.",5,["net to seller"])
Q(C,'advanced',"Annual property taxes of $3,650 are paid in arrears. Closing is on April 10, and the seller owns the day of closing. Using a 365-day year, what is the seller's share?","$1,000 debit to the seller",[("$1,000 credit to the seller","Taxes paid in arrears are owed by the seller, so they are a debit to the seller."),("$2,650 debit to the seller","$2,650 is the buyer's share of the year."),("$990 debit to the seller","This leaves out the day of closing.")],"Arrears taxes → seller's days are a debit to seller, credit to buyer","1. Daily tax = $3,650 ÷ 365 = $10 per day.\n2. Seller's days: Jan 31 + Feb 28 + Mar 31 + Apr 10 = 100 days.\n3. Seller's share = 100 × $10 = **$1,000**.\n4. The taxes have not been paid yet (arrears), so the seller owes this amount: **debit seller, credit buyer**.",5,["prorations"])
Q(C,'intermediate',"A monthly payment is $1,200 for principal and interest, annual property taxes are $3,600, and annual homeowner's insurance is $1,200. What is the monthly PITI payment?","$1,600",[("$1,500","This adds only the monthly taxes."),("$1,300","This adds only the monthly insurance."),("$6,000","This adds annual tax and insurance to the monthly payment.")],"PITI = P&I + monthly taxes + monthly insurance","1. Monthly taxes = $3,600 ÷ 12 = $300.\n2. Monthly insurance = $1,200 ÷ 12 = $100.\n3. PITI = $1,200 + $300 + $100 = **$1,600**.",4,["PITI"])
Q(C,'advanced',"A property earns $60,000 in effective gross income. Operating expenses are $15,000 and annual mortgage payments are $20,000. Using an 8% cap rate, what is the value?","$562,500",[("$312,500","This subtracts the mortgage payments, which are not operating expenses."),("$750,000","This uses gross income instead of NOI."),("$45,000","$45,000 is the NOI, not the value.")],"NOI excludes mortgage payments; value = NOI ÷ cap rate","1. NOI = $60,000 − $15,000 = $45,000 (mortgage payments are **not** subtracted).\n2. Value = $45,000 ÷ 0.08 = **$562,500**.\n3. Check: $562,500 × 0.08 = $45,000.",5,["cap rate"])
Q(C,'basic',"An investor bought a property for $200,000 and sold it for $250,000. What was the percentage of profit based on the purchase price?","25%",[("20%","20% is the profit divided by the sale price, not the purchase price."),("50%","This does not divide by the purchase price correctly."),("80%","80% is the purchase price as a percent of the sale price.")],"Percent change = (new − old) ÷ old","1. Profit = $250,000 − $200,000 = $50,000.\n2. Percent = $50,000 ÷ $200,000 = 0.25 = **25%**.",4,["investment"])
Q(C,'basic',"A room is 12 feet by 15 feet. How many square yards of carpet are needed to cover the floor exactly?","20 square yards",[("180 square yards","180 is the area in square feet."),("60 square yards","This divides by 3 instead of 9."),("9 square yards","This mixes up the conversion factor and the answer.")],"Square yards = square feet ÷ 9","1. Area = 12 × 15 = 180 square feet.\n2. One square yard = 3 ft × 3 ft = 9 square feet.\n3. 180 ÷ 9 = **20 square yards**.",4,["area"])
Q(C,'intermediate',"A buyer's loan is $240,000 at 6% annual interest. What is the interest for the first month?","$1,200",[("$14,400","$14,400 is a full year of interest."),("$1,440","This uses 7.2% instead of 6%."),("$120","This drops a zero.")],"Monthly interest = loan × annual rate ÷ 12","1. Annual interest = $240,000 × 0.06 = $14,400.\n2. First month = $14,400 ÷ 12 = **$1,200**.",4,["interest","financing"])
